-- Register packaged creative entry widgets, preserving the existing artifact-preview identity.
ON CONFLICT(widget_key) DO UPDATE SET name=excluded.name,description=excluded.description,category=excluded.category,icon_key=excluded.icon_key,package_name=excluded.package_name,component_key=excluded.component_key,default_size=excluded.default_size,supported_sizes_json=excluded.supported_sizes_json,data_adapter_key=excluded.data_adapter_key,action_adapter_key=excluded.action_adapter_key,tags_json=excluded.tags_json,is_builtin=excluded.is_builtin,updated_at=unixepoch();
